    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 4, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 5, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 6, $$I cut.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 7, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 8, $$I sleep.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 9, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 10, $$I draw.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 11, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 12, $$I close the door.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 13, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 14, $$I drink.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 15, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 16, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 17, $$I push the goat.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 18, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 19, $$I say hello.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 20, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 21, $$I sing.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 22, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 23, $$I hear the cow.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 24, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 25, $$I look at the blackboard.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 26, $$I look at the sun.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 27, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 28, $$I make a fire.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 29, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 30, $$I give the ball to cat.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 31, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 32, $$I smile.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 33, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 34, $$I cry.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 35, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 36, $$I point at dog.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 37, $$I fly.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 38, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 39, $$I wash my hands.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 40, $$I have a book.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 41, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 42, $$I throw the ball.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 43, $$$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 44, $$I count.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 45, $$The ball is in the box.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 46, $$The ball is in front of the box.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 47, $$The ball flies over the box.$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 48, $$colours$$),
    ('bf6fe85c-a533-4922-9492-afc63d992ce5', 49, $$purple$$),
